import{c as e,Q as d,j as a,m as o}from"./chunks/framework.CWBTDBPu.js";const u=JSON.parse('{"title":"YuRandomTeleport 命令手册","description":"","frontmatter":{"title":"YuRandomTeleport 命令手册"},"headers":[],"relativePath":"plugins/items/yu-random-teleport/commands.md","filePath":"plugins/items/yu-random-teleport/commands.md"}'),l={name:"plugins/items/yu-random-teleport/commands.md"};function r(s,t,i,c,p,n){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="yurandomteleport-命令手册" tabindex="-1">YuRandomTeleport 命令手册 <a class="header-anchor" href="#yurandomteleport-命令手册" aria-label="Permalink to &quot;YuRandomTeleport 命令手册&quot;">​</a></h1><p>主命令为 <code>/yurtp</code>，别名为 <code>/rtp</code>。玩家常用 <code>/rtp</code>，管理员和脚本系统建议使用完整命令 <code>/yurtp</code>。</p><h2 id="命令总览" tabindex="-1">命令总览 <a class="header-anchor" href="#命令总览" aria-label="Permalink to &quot;命令总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>执行者</th><th>说明</th></tr></thead><tbody><tr><td><code>/yurtp</code></td><td><code>yurtp.use</code></td><td>玩家</td><td>将自己随机传送到当前世界的安全位置。</td></tr><tr><td><code>/rtp</code></td><td><code>yurtp.use</code></td><td>玩家</td><td><code>/yurtp</code> 的别名。</td></tr><tr><td><code>/yurtp help</code></td><td>无固定权限；按权限显示内容</td><td>玩家或控制台</td><td>查看帮助。</td></tr><tr><td><code>/yurtp reload</code></td><td><code>yurtp.reload</code></td><td>玩家或控制台</td><td>重载配置、语言文件、世界覆盖、Vault 与 PlaceholderAPI。</td></tr><tr><td><code>/yurtp &lt;玩家&gt;</code></td><td><code>yurtp.teleport.others</code></td><td>管理员或控制台</td><td>将指定在线玩家随机传送到其当前世界。</td></tr><tr><td><code>/yurtp &lt;玩家&gt; &lt;世界&gt;</code></td><td><code>yurtp.teleport.others</code></td><td>管理员或控制台</td><td>将指定在线玩家随机传送到指定世界。</td></tr></tbody></table><h2 id="玩家随机传送" tabindex="-1">玩家随机传送 <a class="header-anchor" href="#玩家随机传送" aria-label="Permalink to &quot;玩家随机传送&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/rtp</span></span>
<span class="line"><span>/yurtp</span></span></code></pre></div><p>执行后插件会：</p><ol><li>检查玩家是否有 <code>yurtp.use</code>。</li><li>检查冷却。</li><li>检查当前世界是否允许随机传送。</li><li>根据当前世界配置读取费用、半径、高度和安全规则。</li><li>如果开启经济且玩家余额足够，进入等待或直接寻找安全点。</li><li>成功传送后扣费并刷新冷却。</li></ol><p>如果找不到安全位置，插件会移除本次冷却，玩家可以立即重试。</p><h2 id="管理员代传送" tabindex="-1">管理员代传送 <a class="header-anchor" href="#管理员代传送" aria-label="Permalink to &quot;管理员代传送&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/yurtp Steve</span></span>
<span class="line"><span>/yurtp Steve resource</span></span></code></pre></div><p>代传送时需要 <code>yurtp.teleport.others</code>。目标玩家仍然需要拥有 <code>yurtp.use</code>，这样可以避免管理员命令绕过服务器的基础使用授权。</p><p>代传送会使用目标玩家所在世界或命令中指定世界的配置。若目标玩家正在冷却，默认会阻止本次传送；拥有 <code>yurtp.bypass.cooldown</code> 的目标玩家可绕过冷却。</p><h2 id="重载配置" tabindex="-1">重载配置 <a class="header-anchor" href="#重载配置" aria-label="Permalink to &quot;重载配置&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/yurtp reload</span></span></code></pre></div><p>重载会重新读取：</p><ul><li><code>config.yml</code></li><li><code>lang/</code> 下的语言文件与旧版兼容 <code>messages.yml</code></li><li>世界配置覆盖</li><li>自定义控制台命令</li><li>Vault 经济挂钩状态</li><li>PlaceholderAPI 扩展注册状态</li></ul><p>重载不会清空已存在的玩家冷却表。如果需要彻底清空运行状态，应重启服务器。</p><h2 id="帮助命令" tabindex="-1">帮助命令 <a class="header-anchor" href="#帮助命令" aria-label="Permalink to &quot;帮助命令&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/rtp help</span></span>
<span class="line"><span>/yurtp help</span></span></code></pre></div><p>帮助内容会根据执行者权限显示。拥有 <code>yurtp.reload</code> 时会显示重载命令。</p><h2 id="tab-补全" tabindex="-1">Tab 补全 <a class="header-anchor" href="#tab-补全" aria-label="Permalink to &quot;Tab 补全&quot;">​</a></h2><p>第一段参数会补全：</p><ul><li><code>reload</code></li><li><code>help</code></li><li>在线玩家名</li><li>已加载世界名</li></ul><p>第二段参数会补全已加载世界名。</p><h2 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to &quot;使用示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>命令</th></tr></thead><tbody><tr><td>玩家在当前世界随机传送</td><td><code>/rtp</code></td></tr><tr><td>管理员将 Alex 传送到当前所在世界的随机点</td><td><code>/yurtp Alex</code></td></tr><tr><td>管理员将 Alex 传送到资源世界</td><td><code>/yurtp Alex resource</code></td></tr><tr><td>修改配置后热重载</td><td><code>/yurtp reload</code></td></tr></tbody></table><h2 id="行为细节" tabindex="-1">行为细节 <a class="header-anchor" href="#行为细节" aria-label="Permalink to &quot;行为细节&quot;">​</a></h2><ul><li>控制台不能在不指定玩家时执行 <code>/yurtp</code>，因为控制台没有当前位置。</li><li>如果指定世界不存在，会返回 <code>world-not-found</code> 消息。</li><li>白名单非空时，只有白名单中的世界允许随机传送。</li><li><code>teleport.wait-seconds</code> 大于 <code>0</code> 且玩家没有 <code>yurtp.bypass.wait</code> 时，玩家会进入等待倒计时。</li><li>等待期间移动位置、受伤、交互、聊天、执行命令或离线，会取消传送并移除本次冷却。</li></ul>`,29)])])}const b=e(l,[["render",r]]);export{u as __pageData,b as default};
